<script setup>
import {computed,ref,onMounted,onBeforeUnmount} from 'vue';
const props=defineProps({record:Object});const emit=defineEmits(['close']);const dialog=ref(null);let opener;
const host=(()=>{try{return window.parent.location.origin===window.location.origin?window.parent.document.body:document.body;}catch{return document.body;}})();
const fields=computed(()=>[['productionOrderNumber','Orden de producción'],['quotationNumber','Cotización'],['accountName','Cuenta'],['contactName','Contacto'],['isBilled','¿Facturado?'],['billNumber','Factura'],['deliveryDate','Fecha de entrega'],['reference','Referencia'],['deliveryAddress','Dirección de envío'],['driver','Conductor'],['trackingNumber','Número de guía']]);
function value(key){const v=props.record?.[key];if(v===undefined||v===null||v==='')return 'Sin información en la copia disponible';if(key==='isBilled')return v===true?'Sí':v===false?'No':String(v);if(key==='deliveryDate'&&/^\d{4}-\d{2}-\d{2}$/.test(v))return v.split('-').reverse().join('/');return String(v);}
function close(){dialog.value?.close();emit('close');opener?.focus?.();}
onMounted(()=>{opener=host.ownerDocument.activeElement;dialog.value.showModal();});onBeforeUnmount(()=>dialog.value?.close());
</script>
<template><Teleport :to="host"><link rel="stylesheet" href="/procesos/account-detail.css"><dialog ref="dialog" class="sigmyp-account-dialog sigmyp-editable-account-dialog sigmyp-production-dialog sigmyp-production-order-dialog sigmyp-referral-dialog" aria-labelledby="referral-title" @cancel.prevent="close"><header class="sigmyp-account-header"><h2 id="referral-title">Remisión {{ record.number }}</h2><button type="button" class="sigmyp-account-close" @click="close">Cerrar ✕</button></header><div class="sigmyp-record-scroll"><div class="production-order-form"><section class="production-order-sidebar"><h3>Remisión</h3><div class="production-order-body sigmyp-account-form"><label v-for="[key,label] in fields" :key="key">{{ label }}<input :value="value(key)" readonly></label><label>Comentarios<textarea :value="record.comments||''" readonly rows="5"></textarea></label></div></section><section class="production-order-products"><h3>Productos <span class="referral-line-count">{{ record.lines?.length||0 }}</span></h3><div class="production-order-body"><div class="sigmyp-account-table-scroll"><table class="production-lines"><thead><tr><th>ID</th><th>Código</th><th>Nombre</th><th>Comentarios</th><th>Cantidad</th></tr></thead><tbody><tr v-for="(line,i) in record.lines||[]" :key="i"><td>{{ line.productId?.replace(/^product-/, '')||'—' }}</td><td>{{ line.code||'—' }}</td><td>{{ line.name }}</td><td class="referral-comments">{{ line.comments||'—' }}</td><td>{{ line.quantity }}</td></tr><tr v-if="!record.lines?.length"><td colspan="5">Sin productos registrados en la copia disponible.</td></tr></tbody></table></div></div></section></div></div><footer class="sigmyp-account-footer"><div class="sigmyp-account-edit-actions"><button type="button" @click="close">Cerrar</button></div></footer></dialog></Teleport></template>
